const samples=1600, arc=[0];let prev=centerAt(0);for(let i=1;i<=samples;i++){const p=centerAt(i/samples*Math.PI*2);arc.push(arc[i-1]+p.distanceTo(prev));prev=p}const length=arc[samples];
function tAtDistance(s){s=((s%length)+length)%length;let lo=0,hi=samples;while(lo<hi){const mid=(lo+hi)>>1;if(arc[mid]<s)lo=mid+1;else hi=mid}const i=Math.max(1,lo),f=(s-arc[i-1])/(arc[i]-arc[i-1]);return ((i-1+f)/samples)*Math.PI*2}
