for(let i=0;i<92;i++){const a=i/92*Math.PI*2,rx=track.rx+27+Math.random()*65,rz=track.rz+30+Math.random()*53,x=rx*Math.cos(a),z=rz*Math.sin(a),w=8+Math.random()*18,h=9+Math.random()*28,dep=8+Math.random()*16;const g=new THREE.Group();g.position.set(x,-.3,z);g.rotation.y=-a;box(g,new THREE.BoxGeometry(w,h,dep),buildingMats[i%buildingMats.length],0,h/2,0);box(g,new THREE.BoxGeometry(w*.75,.25,dep+.2),mat(i%3?'#a8493e':'#8d8a81'),0,h+.1,0);for(let k=0;k<Math.floor(w/2);k++)for(let j=1;j<h/3;j++)box(g,new THREE.BoxGeometry(.55,.75,.08),mat(j%2?'#708486':'#455a61',.3),-w/2+1+k*2.1,j*2.5,dep/2+.06);scene.add(g)}
