{const g=new THREE.Group();const t=.07,p=centerAt(t),d=tangentAt(t),rot=Math.atan2(d.x,d.z);g.position.copy(p);g.rotation.y=rot;box(g,new THREE.BoxGeometry(25,.45,.65),dark,0,8,0);for(const x of [-11,-7,-3,1,5,9]){box(g,new THREE.CylinderGeometry(.42,.42,.3,16),mat('#171b1c'),x,8.35,0);const lamp=new THREE.Mesh(new THREE.CircleGeometry(.27,18),mat('#ee3a33',.25));lamp.position.set(x,8.52,.04);g.add(lamp)}box(g,new THREE.BoxGeometry(.55,8,.55),dark,-12,4,0);box(g,new THREE.BoxGeometry(.55,8,.55),dark,12,4,0);scene.add(g)}
