function makeCar(color,accent='#f1f0e9',number='07',player=false){const root=new THREE.Group();const shell=mat(color,.3,.28),trim=mat(accent,.34,.15),carbon=mat('#111416',.38,.22),wheelGeo=new THREE.CylinderGeometry(.57,.57,.42,24);wheelGeo.rotateZ(Math.PI/2);
 box(root,new THREE.BoxGeometry(1.85,.45,3.55),shell,0,.65,0);box(root,new THREE.BoxGeometry(1.36,.25,2.45),shell,0,.88,.12);box(root,new THREE.BoxGeometry(1.3,.12,1.15),carbon,0,.79,1.36);
 // pointed nose and front wing
