 // rear engine cover, air intake, rear wing
 const cover=new THREE.Mesh(new THREE.ConeGeometry(.65,2.3,5),shell);cover.rotation.x=Math.PI/2;cover.position.set(0,.76,-1.34);root.add(cover);box(root,new THREE.BoxGeometry(.48,.43,.42),carbon,0,1.2,-.12);box(root,new THREE.BoxGeometry(2.65,.16,.48),trim,0,1.52,-2.36);box(root,new THREE.BoxGeometry(2.8,.18,.52),carbon,0,1.76,-2.43);for(const x of [-.95,.95])box(root,new THREE.BoxGeometry(.15,.83,.16),carbon,x,1.22,-2.2);
 // diffuser and sidepod highlights
 box(root,new THREE.BoxGeometry(1.65,.22,.85),carbon,0,.32,-1.6);for(const x of [-1,1]){box(root,new THREE.BoxGeometry(.28,.11,1.5),trim,x,.66,-.1);box(root,new THREE.BoxGeometry(.14,.36,1.12),carbon,x*1.03,.47,-.28);for(const z of [-1.12,1.12]){const tire=new THREE.Mesh(wheelGeo,tireMat);tire.position.set(x*1.08,.54,z);root.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.21,.21,.44,16),trim);hub.rotation.z=Math.PI/2;hub.position.copy(tire.position);root.add(hub);box(root,new THREE.BoxGeometry(.09,.45,.1),carbon,x*1.3,.54,z)}}
 // racing number panel and cockpit accent
 box(root,new THREE.BoxGeometry(.73,.035,.56),trim,0,.92,-.42);const numberCanvas=document.createElement('canvas');numberCanvas.width=128;numberCanvas.height=128;const ctx=numberCanvas.getContext('2d');ctx.fillStyle='#f8f6ee';ctx.font='bold 92px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(number,64,65);const tex=new THREE.CanvasTexture(numberCanvas);const decal=new THREE.Mesh(new THREE.PlaneGeometry(.5,.46),new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide}));decal.rotation.x=-Math.PI/2;decal.position.set(0,.95,-.42);root.add(decal);
 root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});root.userData.player=player;return root}
