const rivals=[];const rivalColors=['#214a77','#e6e2d9','#e9b830','#1b7666','#703c81','#cf723d','#87939b'];for(let i=0;i<7;i++){const car=makeCar(rivalColors[i],i%2?'#20252a':'#f1f0e9',String(2+i).padStart(2,'0'));scene.add(car);rivals.push({mesh:car,s:-13-i*8,lane:(i%2?4:-4)+(Math.random()-.5)*2,speed:Math.random()*1.7+.3,skill:.9+Math.random()*.2})}

const $=s=>document.querySelector(s), ui={start:$('#start-screen'),startBtn:$('#start-btn'),finish:$('#finish-screen'),again:$('#again-btn'),hud:$('#race-hud'),speedPanel:$('#speed-panel'),speed:$('#speed'),gear:$('#gear'),rev:$('#rev-fill'),lap:$('#lap'),lapTime:$('#lap-time'),best:$('#best-lap'),position:$('#position'),countdown:$('#countdown'),count:$('#count-value'),flag:$('#flag'),bottom:$('#bottom-hint'),toast:$('#toast'),sound:$('#sound-btn'),soundState:$('#sound-state')};
const state={mode:'menu',s:8,lane:0,speed:0,steer:0,lap:0,lapElapsed:0,raceElapsed:0,best:Infinity,place:1,muted:false,keys:new Set(),touch:new Set(),toastTimer:0,collisionAt:-10,offroad:false};
function formatTime(seconds){if(!Number.isFinite(seconds))return'—:—.---';const m=Math.floor(seconds/60),s=seconds%60;return`${String(m).padStart(2,'0')}:${s.toFixed(3).padStart(6,'0')}`}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');state.toastTimer=1.5}
function isDown(...names){return names.some(n=>state.keys.has(n)||state.touch.has(n))}
function setCarPose(mesh,s,lane,offsetY=0){const t=tAtDistance(s),p=pointAt(s,lane,offsetY);mesh.position.copy(p);mesh.rotation.set(0,Math.atan2(tangentAt(t).x,tangentAt(t).z),0)}
function startRace(){state.mode='countdown';state.s=8;state.lane=0;state.speed=0;state.lap=0;state.lapElapsed=0;state.raceElapsed=0;state.best=Infinity;state.place=1;state.collisionAt=-10;rivals.forEach((r,i)=>{r.s=25+i*11;r.lane=(i%2?4:-4)+(Math.random()-.5)*1.5;r.speed=0});ui.start.classList.add('leaving');ui.finish.classList.add('hidden');ui.hud.classList.add('visible');ui.speedPanel.style.opacity='1';ui.bottom.style.opacity='1';ui.flag.classList.add('visible');ui.countdown.classList.add('visible');ui.count.textContent='3';let n=3;const countdown=setInterval(()=>{n--;if(n>0){ui.count.textContent=String(n)}else if(n===0){ui.count.textContent='GO';ui.flag.classList.remove('visible');state.mode='race'}else{ui.countdown.classList.remove('visible');clearInterval(countdown)}},850);}
function finishRace(){state.mode='finish';const won=state.place===1;$('#finish-title').innerHTML=won?'RACE<br><em>WINNER.</em>':'RACE<br><em>COMPLETE.</em>';$('#finish-copy').textContent=won?'A flawless drive through the streets of Monaco.':`You brought it home in P${state.place}. The next race is yours.`;$('#final-position').textContent=`P${state.place}`;$('#final-best').textContent=formatTime(state.best);ui.finish.classList.remove('hidden')}
ui.startBtn.addEventListener('click',startRace);ui.again.addEventListener('click',startRace);
