document.querySelectorAll('[data-control]').forEach(btn=>{const k=btn.dataset.control;btn.addEventListener('pointerdown',e=>{e.preventDefault();state.touch.add(k);btn.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(ev,()=>state.touch.delete(k))});
ui.sound.addEventListener('click',()=>{state.muted=!state.muted;ui.soundState.textContent=state.muted?'OFF':'ON';ui.sound.classList.toggle('muted',state.muted);if(!state.muted)startAudio()});
let audioCtx,osc,gain;function startAudio(){if(state.muted)return;try{audioCtx??=new AudioContext();if(osc)return;osc=audioCtx.createOscillator();gain=audioCtx.createGain();osc.type='sawtooth';gain.gain.value=.0001;osc.connect(gain);gain.connect(audioCtx.destination);osc.start()}catch{}}
function updateAudio(){if(!audioCtx||!osc)return;const rpm=75+state.speed*3.1;osc.frequency.setTargetAtTime(rpm,audioCtx.currentTime,.08);gain.gain.setTargetAtTime(state.mode==='race'?.018+state.speed/6000:.0001,audioCtx.currentTime,.12)}
function resize(){renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()};window.addEventListener('resize',resize);

const clock=new THREE.Clock();let raceClock=0;const lookTarget=new THREE.Vector3();
function update(dt){dt=Math.min(dt,.04);state.toastTimer=Math.max(0,state.toastTimer-dt);if(state.toastTimer===0)ui.toast.classList.remove('show');
 const active=state.mode==='race';if(active){state.raceElapsed+=dt;state.lapElapsed+=dt;const throttle=isDown('w','arrowup','throttle'),brake=isDown('s','arrowdown','brake'),left=isDown('a','arrowleft','left'),right=isDown('d','arrowright','right');const steer=(right?1:0)-(left?1:0);state.steer=THREE.MathUtils.damp(state.steer,steer,7,dt);if(throttle)state.speed=Math.min(94,state.speed+31*dt);else state.speed=Math.max(0,state.speed-(5+state.speed*.028)*dt);if(brake)state.speed=Math.max(0,state.speed-48*dt);
 state.lane=THREE.MathUtils.clamp(state.lane+state.steer*(3.4+state.speed*.075)*dt,-15,15);const onTrack=Math.abs(state.lane)<track.width/2-1.6;if(!onTrack)state.speed=Math.max(0,state.speed-(13+state.speed*.12)*dt);if(Math.abs(state.lane)>13.4){if(!state.offroad)showToast('TRACK LIMITS · SLOW DOWN');state.offroad=true}else state.offroad=false;
 const oldLap=Math.floor(state.s/length);state.s+=state.speed*dt;const newLap=Math.floor(state.s/length);if(newLap>oldLap){state.lap++;state.best=Math.min(state.best,state.lapElapsed);state.lapElapsed=0;if(state.lap>=3)finishRace();else showToast(`LAP ${state.lap+1} · ${formatTime(state.best)} BEST`)}
 for(const r of rivals){const desired=67+r.speed*6;r.s+=desired*dt;if(r.s>state.s+length*.18)r.s-=length*.98;const delta=((r.s-state.s+length*1.5)%length)-length/2;const lateral=Math.abs(r.lane-state.lane);if(Math.abs(delta)<22&&lateral<3.1&&state.raceElapsed-state.collisionAt>1.3){state.collisionAt=state.raceElapsed;state.speed=Math.max(16,state.speed*.68);r.s+=delta>0?5:-5;showToast('CONTACT · CAR DAMAGED');}setCarPose(r.mesh,r.s,r.lane,.05)}
 const standings=1+rivals.filter(r=>((r.s-state.s+length*1.5)%length)<length/2).length;state.place=standings;ui.position.textContent=`P${standings}`;ui.lap.textContent=String(Math.min(state.lap+1,3)).padStart(2,'0');ui.lapTime.textContent=formatTime(state.lapElapsed);ui.best.textContent=formatTime(state.best);ui.speed.textContent=String(Math.round(state.speed*3.6)).padStart(3,'0');ui.gear.textContent=String(Math.min(8,Math.max(1,Math.floor(state.speed/12)+1));ui.rev.style.width=`${Math.min(100,(state.speed%12)/12*100)}%`;$('#drs').textContent=state.speed>53?'OPEN':'OFF';
 }
 setCarPose(playerCar,state.s,state.lane,.08);
 const t=tAtDistance(state.s),forward=tangentAt(t),pos=playerCar.position;let desiredPos,desiredLook;if(active||state.mode==='paused'||state.mode==='finish'){desiredPos=pos.clone().addScaledVector(forward,-17).add(new THREE.Vector3(0,7.3,0));desiredLook=pos.clone().addScaledVector(forward,13).add(new THREE.Vector3(0,1.1,0));camera.position.lerp(desiredPos,1-Math.exp(-dt*2.7));lookTarget.lerp(desiredLook,1-Math.exp(-dt*3.4));camera.fov=THREE.MathUtils.damp(camera.fov,54+state.speed*.045,2,dt);camera.updateProjectionMatrix()}else{const tm=clock.elapsedTime;desiredPos=new THREE.Vector3(215+Math.sin(tm*.06)*9,150,225+Math.cos(tm*.06)*10);camera.position.lerp(desiredPos,1-Math.exp(-dt*.5));lookTarget.lerp(new THREE.Vector3(0,0,0),1-Math.exp(-dt*.7));camera.fov=54;camera.updateProjectionMatrix()}
 camera.lookAt(lookTarget);updateAudio();}
function animate(){requestAnimationFrame(animate);const dt=clock.getDelta();update(dt);renderer.render(scene,camera)}
// Cinematic opening view and a stationary grid; the world is fully live before the lights go out.
setCarPose(playerCar,state.s,state.lane,.08);for(let i=0;i<rivals.length;i++)setCarPose(rivals[i].mesh,rivals[i].s,rivals[i].lane,.05);camera.position.set(215,150,225);camera.lookAt(0,0,0);animate();

